package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Document struct {
	ID       int    `json:"id"`
	Title    string `json:"title"`
	Content  string `json:"content"`
	OwnerID  int    `json:"owner_id"`
	Classify string `json:"classification"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchDocuments allows full-text search with optional filter
func searchDocuments(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var req struct {
		Query      string `json:"query"`
		FilterExpr string `json:"filter_expr"`
		Limit      int    `json:"limit"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid JSON", 400)
		return
	}

	// Sanitize the main query parameter
	req.Query = strings.ReplaceAll(req.Query, "'", "''")

	if req.Limit <= 0 || req.Limit > 100 {
		req.Limit = 20
	}

	// Build the SQL - filter_expr allows advanced users to specify
	// additional WHERE conditions like "classification = 'public'"
	baseSQL := fmt.Sprintf(
		"SELECT id, title, content, owner_id, classification FROM documents WHERE to_tsvector('english', content) @@ plainto_tsquery('english', '%s')",
		req.Query,
	)

	if req.FilterExpr != "" {
		// NOTE: filter_expr is passed through for power users
		// The application relies on the database user having read-only access
		baseSQL += " AND " + req.FilterExpr
	}

	baseSQL += fmt.Sprintf(" LIMIT %d", req.Limit)

	rows, err := db.Query(baseSQL)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Search failed", 500)
		return
	}
	defer rows.Close()

	var docs []Document
	for rows.Next() {
		var d Document
		if err := rows.Scan(&d.ID, &d.Title, &d.Content, &d.OwnerID, &d.Classify); err != nil {
			continue
		}
		docs = append(docs, d)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(docs)
}

// healthCheck endpoint for LB
func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/documents/search", searchDocuments)
	http.HandleFunc("/health", healthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
